+        let mut offset = 0;
+        // Tiny writes (carry across groups) and writes several segments long.
+        for size in [1_usize, 2, 300_000, 5, 3_000_001, 700_000, 1].iter().cycle() {
+            if offset >= data.len() {
+                break;
+            }
+            let end = (offset + size).min(data.len());
+            encoder.write_all(&data[offset..end]).unwrap();
+            offset = end;
+        }
